import XCTest

@MainActor final class AchievementRecoveryJourneyTests:XCTestCase {
    private func tap(_ id:String,_ app:XCUIApplication){let button=app.buttons[id];XCTAssertTrue(button.waitForExistence(timeout:15),id);for _ in 0..<10 where !button.isHittable{app.swipeUp(velocity:.slow)};XCTAssertTrue(button.isHittable,id);button.tap()}
    private func shot(_ name:String,_ app:XCUIApplication){let capture=XCTAttachment(screenshot:app.screenshot());capture.name=name;capture.lifetime = .keepAlways;add(capture)}
    func testLostCloudResponseKeepsAwardPendingAcrossRelaunchAndRecoversWithoutNewPracticeOrDuplicateXP()async throws{
        continueAfterFailure=false;let gate=LocalMembershipServer(),relay=LocalNostrRelay();defer{gate.stop();relay.stop()};gate.status(["allow":false]);try await gate.start();try await relay.start{frame,c in if frame.first as?String=="REQ",let sub=frame[1]as?String{relay.send(["EOSE",sub],to:c)}}
        let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_ENTRY_INITIAL_LANGUAGE":"en","PIYALI_ENTRY_INITIAL_THEME":"light","PIYALI_SETTINGS_FIXTURE":"1","PIYALI_FLASHCARD_FIXTURE":"1","PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_ACHIEVEMENT_DELIVERY_UI":"1","PIYALI_ACHIEVEMENT_RETRY_UI":"1","PIYALI_FIRESTORE_EMULATOR_PORT":"8330","PIYALI_ACHIEVEMENT_RETRY_RELAY":relay.url,"PIYALI_ACHIEVEMENT_RETRY_GATE":gate.url+"/status"];app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();handleInitialPaperPencil(app);let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Recovery Learner");tap("entryKeyboardDone",app);tap("createAccount",app);handleInitialPaperPencil(app);tap("onboardingPractice",app)
        let menuOptions=app.descendants(matching:.any).matching(NSPredicate(format:"label == %@","Spanish")).allElementsBoundByIndex
        guard let spanish=menuOptions.first(where:{$0.isHittable})else{let tree=XCTAttachment(string:app.debugDescription);tree.name="Recovery onboarding menu hierarchy";tree.lifetime = .keepAlways;add(tree);throw NSError(domain:"OnboardingMenuChoiceNotHittable",code:1)}
        spanish.tap();tap("startLearning",app);XCTAssertTrue(app.staticTexts["XP 20"].waitForExistence(timeout:15))
        tap("productMenu",app);tap("productModeMenu",app);tap("productMode-cards",app);tap("flashcardTile-pre-a1-people-1",app);let answer=app.textFields["flashcardAnswer"];XCTAssertTrue(answer.waitForExistence(timeout:8));answer.tap();answer.typeText("mamá\n");XCTAssertTrue(app.staticTexts["flashcardReward"].waitForExistence(timeout:15));tap("flashcardRate-hard",app);XCTAssertTrue(app.buttons["achievementContinue"].waitForExistence(timeout:25));tap("achievementContinue",app)
        app.terminate();app.launch();handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:20));XCTAssertFalse(app.buttons["achievementContinue"].exists);tap("focusAchievements",app);XCTAssertTrue(app.staticTexts["achievementSyncStatus"].waitForExistence(timeout:15));XCTAssertEqual(app.staticTexts["achievementCollectionCount"].label,"1 of 76 collected");shot("Native durable achievement recovery pending after restart",app)
        gate.status(["allow":true]);let cleared=NSPredicate(format:"exists == false");let recovered=expectation(for:cleared,evaluatedWith:app.staticTexts["achievementSyncStatus"]);await fulfillment(of:[recovered],timeout:45);XCTAssertEqual(app.staticTexts["achievementCollectionCount"].label,"1 of 76 collected");XCTAssertFalse(app.buttons["achievementContinue"].exists);shot("Native achievement recovery confirmed without another review",app)
        tap("achievementCollectionClose",app);let xp=app.staticTexts["XP 26"];XCTAssertTrue(xp.waitForExistence(timeout:8));XCTAssertEqual(xp.label,"XP 26");app.terminate();app.launch();handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:20));XCTAssertFalse(app.buttons["achievementContinue"].exists);XCTAssertEqual(app.staticTexts["XP 26"].label,"XP 26");XCTAssertTrue(relay.frames().filter{$0.first as?String=="EVENT"}.isEmpty);XCTAssertGreaterThan(gate.requests().count,1)
    }
}
